function validate([mat]) {
  if (!Array.isArray(mat) || mat.length < 1 || mat.length > 6) return 'mat needs 1 to 6 rows.';
  const n = Array.isArray(mat[0]) ? mat[0].length : 0;
  if (n < 1 || n > 6) return 'Each row needs 1 to 6 cells.';
  for (const row of mat) {
    if (!Array.isArray(row) || row.length !== n) return 'All rows must have the same length.';
    if (row.some(v => !Number.isInteger(v) || v < 1 || v > 9)) return 'Each cell is a digit from 1 to 9.';
  }
  return null;
}

