function mostFrequentPrime(mat) {
  const m = mat.length, n = mat[0].length;
  const limit = 10 ** Math.max(m, n);
  const composite = new Uint8Array(limit + 1);
  composite[0] = composite[1] = 1;
  for (let p = 2; p * p <= limit; p++) if (!composite[p]) for (let q = p * p; q <= limit; q += p) composite[q] = 1;
  const made = [];
  for (let i = 0; i < m; i++) for (let j = 0; j < n; j++) {
    for (let di = -1; di <= 1; di++) for (let dj = -1; dj <= 1; dj++) {
      if (di === 0 && dj === 0) continue;
      let text = '';
      for (let s = 0; ; s++) {
        const a = i + s * di, b = j + s * dj;
        if (a < 0 || a >= m || b < 0 || b >= n) break;
        text += String(mat[a][b]);
        made.push(Number(text));
      }
    }
  }
  const tally = new Map();
  for (const v of made) if (v > 10 && !composite[v]) tally.set(v, (tally.get(v) || 0) + 1);
  const ranked = [...tally.keys()].sort((x, y) => tally.get(y) - tally.get(x) || y - x);
  return ranked.length ? ranked[0] : -1;
}

