function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const pools = [[1, 2, 3, 4, 5, 6, 7, 8, 9], [1, 3, 7, 9], [2, 4, 5, 6, 8], [1, 3], [1, 9, 7]];
  const pool = size === 'large' && rand() < 0.6 ? pools[0] : pools[int(0, pools.length - 1)];
  const m = size === 'large' ? int(5, 6) : int(1, 3);
  const n = size === 'large' ? 6 : int(1, 3);
  const mat = Array.from({ length: m }, () => Array.from({ length: n }, () => pool[int(0, pool.length - 1)]));
  return [mat];
}
